"""Frozen build rules (19 Nov 2026, before the v1.0 freeze): the single-file src/main.py generated by
tools/make_bundle.py, its argument forms, the never-fail fallback, exact timestamps, unit quaternions and
input variants that must not change the output. SYNTHETIC inputs, plus official copies when on disk."""

import importlib.util
import math
import os
import subprocess
import sys
from pathlib import Path

import pytest

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT / "tools"))
import make_bundle  # noqa: E402
import synth_euroc  # noqa: E402

from vortex import check_output  # noqa: E402
from vortex.rowspec import data_lines  # noqa: E402

DATA = Path(os.environ.get("VORTEX_DATA", ROOT / "data"))


@pytest.fixture(scope="module", params=make_bundle.LAYOUTS)
def single(request, tmp_path_factory):
    """The bundle file in each layout (PLAIN and CHUNKED must pass the same B1/B2/B4/B5 tests, bundle rule K (b))."""
    p = tmp_path_factory.mktemp("single_" + request.param) / "main.py"
    make_bundle.write_single(str(p), request.param)
    return p


@pytest.fixture(scope="module")
def plain(tmp_path_factory):
    p = tmp_path_factory.mktemp("plain") / "main.py"
    make_bundle.write_single(str(p), "plain")
    return p


def _load(path, name="vortex_single_under_test"):
    spec = importlib.util.spec_from_file_location(name, path)
    mod = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(mod)
    return mod


@pytest.fixture(scope="module")
def base_csv(tmp_path_factory):
    p = tmp_path_factory.mktemp("base") / "imu.csv"
    synth_euroc.write(str(p), rows=3000, seed=3)
    return p


def _run(single, args, cwd, flags=("-S",)):
    return subprocess.run([sys.executable, *flags, str(single), *map(str, args)], cwd=str(cwd),
                          capture_output=True, text=True, timeout=300)


# ---------------------------------------------------------------- 1. single file, reachability
def test_single_file_is_pathfinder_with_a_header_and_passes_the_check(plain):
    text = plain.read_text(encoding="utf-8")
    assert make_bundle.check_single(text) == []
    assert "GENERATED by tools/make_bundle.py" in text
    import ast
    src = (ROOT / "pathfinder.py").read_text(encoding="utf-8")
    fns = lambda t: sorted(n.name for n in ast.parse(t).body if isinstance(n, ast.FunctionDef))  # noqa: E731
    assert fns(text) == fns(src)                                  # every function kept; only OFF sides folded
    assert text.count('"""') == 2                                 # the header is the only docstring left


def test_folding_keeps_the_on_side_only():
    src = ("A_ON = True\nB_ON = False\n\ndef f(x):\n    '''doc'''\n    a, b = A_ON, B_ON\n"
           "    if a and x:\n        y = 1\n    else:\n        y = 2\n    if b:\n        y = 3\n"
           "    if not A_ON:\n        y = 4\n    return y if B_ON or x else -1\n")
    import ast
    tree = make_bundle._Fold(make_bundle._switches(ast.parse(src))).visit(ast.parse(src))
    out = ast.unparse(make_bundle._drop_dead_assignments(tree))
    assert "doc" not in out and "y = 3" not in out and "y = 4" not in out and "a, b" not in out
    ns = {}
    exec(compile(out, "f", "exec"), ns)                           # same results as the original
    ref = {}
    exec(compile(src, "f", "exec"), ref)
    for x in (0, 1):
        assert ns["f"](x) == ref["f"](x)


@pytest.mark.parametrize("planted", [
    "import ctypes\n", "from importlib import util\n", "import numpy\n", "x = __import__('math')\n",
    "eval('1')\n", "P = '__pycache__/pathfinder.cpython-314.pyc'\n", "import marshal\n", "L = 'core.dll'\n",
    "from . import x\n", "match 1:\n    case 1:\n        pass\n" if sys.version_info < (3, 10) else "x = (y := 1)\n",
])
def test_reachability_check_refuses_c_ctypes_bytecode_and_non_stdlib(planted):
    text = make_bundle.single_text() + "\n" + planted
    bad = make_bundle.check_single(text)
    if planted.startswith("x = (y"):
        assert bad == []                                    # 3.8+ syntax is fine
    else:
        assert bad, planted


def test_single_file_output_equals_the_repo_build(single, base_csv, tmp_path):
    a, b = tmp_path / "repo.txt", tmp_path / "single.txt"
    assert subprocess.run([sys.executable, "-S", str(ROOT / "main.py"), str(base_csv), str(a)]).returncode == 0
    assert _run(single, [base_csv, b], tmp_path).returncode == 0
    assert a.read_bytes() == b.read_bytes()


OFFICIAL = [DATA / "official" / "MH_03_medium_a_s1", DATA / "official" / "MH_03_medium_b_s2",
            DATA / "official_tumvi" / "dataset-room3_512_16_a_s1", DATA / "official_tumvi" / "dataset-room3_512_16_b_s3"]


@pytest.mark.parametrize("seq", OFFICIAL, ids=lambda p: p.name)
def test_single_file_identical_on_official_copies_with_exact_timestamps(single, seq, tmp_path):
    imu = seq / "mav0" / "imu0" / "data.csv"
    if not imu.exists():
        pytest.skip("official copy not on disk: %s" % seq.name)
    a, b = tmp_path / "repo.txt", tmp_path / "single.txt"
    assert subprocess.run([sys.executable, "-S", str(ROOT / "main.py"), str(imu), str(a)]).returncode == 0
    assert _run(single, [imu, b], tmp_path).returncode == 0
    assert a.read_bytes() == b.read_bytes()
    _assert_exact_timestamps_and_unit_quaternions(imu, b)


# ---------------------------------------------------------------- 3. never fail
def test_estimator_failure_writes_a_constant_pose_for_every_row(plain, base_csv, tmp_path, monkeypatch, capsys):
    mod = _load(plain)

    def boom(*a, **k):
        raise ZeroDivisionError("forced")
    monkeypatch.setattr(mod, "_run_smoothed", boom)
    out = tmp_path / "est.txt"
    assert mod.main(["main.py", str(base_csv), str(out)]) == 0
    err = capsys.readouterr().err
    assert "ZeroDivisionError: forced" in err and "constant pose" in err
    with open(base_csv, "rb") as f:
        n_in = sum(1 for _ in data_lines(f))
    lines = out.read_bytes().splitlines()
    assert len(lines) == n_in == 3000
    assert all(l.split()[1:] == [b"0.000000", b"0.000000", b"0.000000", b"0.0000000", b"0.0000000", b"0.0000000",
                                 b"1.0000000"] for l in lines)
    assert check_output.check(str(base_csv), str(out))["ok"]
    _assert_exact_timestamps_and_unit_quaternions(base_csv, out)


def test_failure_mid_write_and_memory_error_still_give_every_row(plain, base_csv, tmp_path, monkeypatch):
    mod = _load(plain, "vortex_single_fail2")
    real = mod._run

    def half(src, dst, *a, **k):
        real(src, dst, *a, **k)
        raise MemoryError()
    monkeypatch.setattr(mod, "_run", half)
    out = tmp_path / "est.txt"
    assert mod.main(["main.py", str(base_csv), str(out)]) == 0
    assert check_output.check(str(base_csv), str(out))["ok"]
    assert mod.LAST["fallback"].startswith("MemoryError")


def test_fallback_through_the_command_line(single, tmp_path):
    bad = tmp_path / "imu.csv"                       # every value bad: the estimator copes; still one pose per row
    bad.write_bytes(b"#t,a,b,c,d,e,f\n" + b"".join(b"%d,x,y,z,u,v,w\n" % (10**18 + 5 * 10**6 * i) for i in range(50)))
    p = _run(single, [bad, tmp_path / "o.txt"], tmp_path)
    assert p.returncode == 0
    assert check_output.check(str(bad), str(tmp_path / "o.txt"))["ok"]


# ---------------------------------------------------------------- 4. timestamps, quaternions
def _assert_exact_timestamps_and_unit_quaternions(imu, out):
    with open(imu, "rb") as f:
        ts = [l.split(b",", 1)[0].strip() for l in data_lines(f)]
    lines = Path(out).read_bytes().split(b"\n")
    assert lines[-1] == b""
    lines = lines[:-1]
    assert len(lines) == len(ts)
    for t, line in zip(ts, lines):
        f = line.split(b" ")
        assert len(f) == 8
        if t.isdigit():
            ns = int(t)
            assert f[0] == (str(ns // 10**9) + "." + "%09d" % (ns % 10**9)).encode(), (t, f[0])
        q = [float(x) for x in f[4:8]]
        assert abs(math.sqrt(sum(x * x for x in q)) - 1.0) < 1e-6, line


def test_timestamps_are_integer_arithmetic_exact(single, tmp_path):
    rows = [b"#timestamp [ns],w_x,w_y,w_z,a_x,a_y,a_z"]
    stamps = [5, 999999999, 1000000000, 1000000001, 1403636579758555392, 18446744073709551615]
    stamps += [1403636580000000000 + 5000000 * i for i in range(400)]
    for t in stamps:
        rows.append(b"%d,0.001,-0.002,0.003,0.1,0.2,9.8" % t)
    rows.append(b"0001403636590000000000,0.001,-0.002,0.003,0.1,0.2,9.8")     # leading zeros
    imu = tmp_path / "imu.csv"
    imu.write_bytes(b"\n".join(rows) + b"\n")
    out = tmp_path / "o.txt"
    assert _run(single, [imu, out], tmp_path).returncode == 0
    _assert_exact_timestamps_and_unit_quaternions(imu, out)
    last = out.read_bytes().splitlines()[-1].split()[0]
    assert last == b"1403636590.000000000"
    assert out.read_bytes().splitlines()[0].split()[0] == b"0.000000005"


# ---------------------------------------------------------------- 5. input variants
def _variant(base, kind):
    lines = base.read_bytes().split(b"\n")
    if lines[-1] == b"":
        lines = lines[:-1]
    head, body = lines[0], lines[1:]
    assert head.startswith(b"#")
    if kind == "crlf":
        return b"\r\n".join(lines) + b"\r\n"
    if kind == "header_without_hash":
        return b"\n".join([head[1:]] + body) + b"\n"
    if kind == "no_header":
        return b"\n".join(body) + b"\n"
    if kind == "blank_lines":
        out = [head, b""]
        for i, l in enumerate(body):
            out.append(l)
            if i % 97 == 0:
                out += [b"", b"   "]
        return b"\n".join(out) + b"\n"
    if kind == "extra_columns":
        return b"\n".join([head + b",temp,flag"] + [l + b",36.6,1" for l in body]) + b"\n"
    if kind == "spaces_after_commas":
        return b"\n".join([head] + [l.replace(b",", b", ") for l in body]) + b"\n"
    if kind == "all_at_once":
        return b"\r\n".join([head[1:] + b",temp"] + [b""] + [l.replace(b",", b", ") + b", 1" for l in body]) + b"\r\n"
    raise ValueError(kind)


@pytest.mark.parametrize("kind", ["crlf", "header_without_hash", "no_header", "blank_lines", "extra_columns",
                                  "spaces_after_commas", "all_at_once"])
def test_input_variants_do_not_change_the_output(single, base_csv, tmp_path, kind):
    ref = tmp_path / "ref.txt"
    assert _run(single, [base_csv, ref], tmp_path).returncode == 0
    imu = tmp_path / ("%s.csv" % kind)
    imu.write_bytes(_variant(base_csv, kind))
    out = tmp_path / "o.txt"
    p = _run(single, [imu, out], tmp_path)
    assert p.returncode == 0 and p.stderr == ""
    assert out.read_bytes() == ref.read_bytes(), kind
    assert check_output.check(str(imu), str(out))["ok"]
    assert not list(tmp_path.glob("*.vortex_in.csv"))               # the front end's temporary copy is removed


# ---------------------------------------------------------------- 2. invocation
def _seq(tmp_path, base_csv, layout):
    d = tmp_path / "seq"
    p = d.joinpath(*layout)
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_bytes(base_csv.read_bytes())
    return d


@pytest.mark.parametrize("layout", [("imu0", "data.csv"), ("mav0", "imu0", "data.csv"), ("data.csv",),
                                    ("MH_99_whatever.csv",)])
@pytest.mark.parametrize("flags", [("-S",), ()], ids=["S", "noS"])
def test_no_arguments_searches_the_current_folder(single, base_csv, tmp_path, layout, flags):
    ref = tmp_path / "ref.txt"
    assert _run(single, [base_csv, ref], tmp_path).returncode == 0
    d = _seq(tmp_path, base_csv, layout)
    p = _run(single, [], d, flags)
    assert p.returncode == 0, p.stderr
    assert (d / "estimated_trajectory.txt").read_bytes() == ref.read_bytes()


def test_every_argument_form_from_another_folder(single, base_csv, tmp_path):
    ref = tmp_path / "ref.txt"
    assert _run(single, [base_csv, ref], tmp_path).returncode == 0
    d = _seq(tmp_path, base_csv, ("mav0", "imu0", "data.csv"))
    imu = d / "mav0" / "imu0" / "data.csv"
    work = tmp_path / "work"
    work.mkdir()
    outdir = tmp_path / "outdir"
    outdir.mkdir()
    forms = [([imu], work / "estimated_trajectory.txt"),
             ([d], work / "estimated_trajectory.txt"),
             ([imu, tmp_path / "a.txt"], tmp_path / "a.txt"),
             ([d, outdir], outdir / "estimated_trajectory.txt"),
             (["--input", imu, "--output", tmp_path / "b.txt"], tmp_path / "b.txt"),
             (["-i", imu, "-o", tmp_path / "c.txt"], tmp_path / "c.txt"),
             (["--input=%s" % imu, "--output=%s" % (tmp_path / "e.txt")], tmp_path / "e.txt"),
             (["-o", tmp_path / "d.txt", "-i", d], tmp_path / "d.txt")]
    for flags in (("-S",), (), ("-I",), ("-I", "-S")):
        for args, out in forms:
            if out.exists():
                out.unlink()
            p = _run(single, args, work, flags)
            assert p.returncode == 0, (flags, args, p.stderr)
            assert out.read_bytes() == ref.read_bytes(), (flags, args)


def test_bad_arguments_exit_2_with_usage(single, tmp_path):
    p = _run(single, [], tmp_path)                                  # empty folder: nothing to read
    assert p.returncode == 2 and "no IMU csv found" in p.stderr and "usage" in p.stderr
    (tmp_path / "a.csv").write_text("1,2,3,4,5,6,7\n")
    (tmp_path / "b.csv").write_text("1,2,3,4,5,6,7\n")
    p = _run(single, [], tmp_path)                                  # two csv files: ambiguous
    assert p.returncode == 2 and "found 2" in p.stderr
    assert _run(single, ["a.csv", "x.txt", "extra"], tmp_path).returncode == 2
    assert _run(single, ["--bogus"], tmp_path).returncode == 2
    h = _run(single, ["--help"], tmp_path)
    assert h.returncode == 0 and "usage" in h.stderr


def test_unreadable_input_exits_1(single, tmp_path):
    p = _run(single, [tmp_path / "missing.csv", tmp_path / "o.txt"], tmp_path)
    assert p.returncode == 1
